class ArrayIntersection():
    def __init__(self, arr1, arr2):
        self.arr1 = arr1
        self.arr2 = arr2

    def intersection(self):
        intersection = []
        i, j = 0, 0
        while i < len(self.arr1) and j < len(self.arr2):
            if self.arr1[i] == self.arr2[j]:
                intersection.append(self.arr1[i])
                i += 1
                j += 1
            elif self.arr1[i] < self.arr2[j]:
                i += 1
            else:
                j += 1
        return intersection

